func commitFiles(r *repo, rev string) ([]string, error) {
	out, err := r.git("rev-list", "--parents", "-n", "1", rev)
	if err != nil {
		return nil, err
	}
	fields := strings.Fields(out)
	var sets []map[string]bool
	if len(fields) <= 1 {
		out, err := r.git("diff-tree", "--root", "--no-commit-id", "--name-only", "-r", "--no-renames", "--relative", rev)
		if err != nil {
			return nil, err
		}
		set := map[string]bool{}
		for _, p := range strings.Fields(out) {
			set[p] = true
		}
		sets = append(sets, set)
	} else {
		for _, parent := range fields[1:] {
			out, err := r.git("diff-tree", "--no-commit-id", "--name-only", "-r", "--no-renames", "--relative", parent, rev)
			if err != nil {
				return nil, err
			}
			set := map[string]bool{}
			for _, p := range strings.Split(out, "\n") {
				if p != "" {
					set[p] = true
				}
			}
			sets = append(sets, set)
		}
	}
	counts := map[string]int{}
	for _, set := range sets {
		for p := range set {
			counts[p]++
		}
	}
	var result []string
	for p, n := range counts {
		if n == len(sets) {
			result = append(result, p)
		}
	}
	sort.Strings(result)
	return result, nil
}

